"…女房がたに、名無しの紅を。北の大路の大臣家が。…そうか。去年の暮れから、もう始まっておったのだな":"...Nameless rouge for the ladies-in-waiting. From the Minister's house on the northern avenue. ...I see. So it had already begun by the end of last year.",
