"どの家の車が何刻に来て何刻に帰るか、全部知っている。待つ者たちの愚痴の聞き役":"Knows when every household's cart comes and goes. The one who hears the waiting men's grumbles.",
"どの家も煙が上がっとる":"Smoke's rising from every house.",
"どの家も煙が上がる。飯の刻だ":"Smoke rising from every house. Mealtime.",
"どの道で運ぶ？":"Which road should we take?",
"どの道を行けばいい？":"Which road should we take?",
"どの邸が羽振りがいいか、屋根でわかる":"You can tell which mansions are flush by their roofs.",
"どの邸の衣がいちばん汚れるか、知っとるよ":"I know which mansion's clothes come in the dirtiest.",
"どれも違ってよかった":"Each was different, and good",
"どんな人？":"What kind of people?",
"どんな噂？":"What rumors?",
"どんな夢じゃ":"What kind of dream?",
