"保行どのが門を閉めた":"Yasuyuki shut the gate",
"保長":"District Chief",
"信じてる？":"Do you believe it?",
"信じる？":"Do you believe it?",
"信濃から十頭増えましたので":"We got ten more horses from Shinano, sir.",
"信濃の牧から十頭届いた":"Ten horses arrived from a ranch in Shinano",
"信濃の牧から十頭届いた。毛並みがええ":"Ten head arrived from the Shinano pastures. Fine coats.",
"修理職":"Shuri-shiki (Office of Palace Repairs)",
"修行を積み、いつか小さな堂を守ること":"To deepen his training and one day keep a small temple hall",
"俵の数が帳面と合わん。数え直しだ":"The bale count doesn't match the ledger. Count again.",
"俵の米を少し、男の子の袖に入れてやった。男の子は何も言わずに、空き家の闇へ消えた":"You slip a little rice from the bale into the boy's sleeve. Without a word, he vanishes into the dark of the empty house.",
"倉の中身を帳面で知っている。倉守の老松とは、帳面と実物のずれで言い争う仲":"He knows what's in the storehouses from the ledgers. He and Oimatsu, the storehouse keeper, often argue when the books and the goods don't match.",
"倉の出し入れは帳面で見る":"I track what goes in and out of the storehouses by the books.",
"倉の布が一反足りん":"One bolt of cloth is missing from the storehouse.",
"倉の帳と中身が合わん。三度目の数え直しだ":"The ledger and the contents don't match. Third recount.",
"倉の鍵は大蔵の役人しか持っとらん":"Only Treasury officials hold the storehouse keys.",
"倉へ近づくでない。…鉄の者は盗まんか":"Keep away from the storehouses. ...Do iron ones steal, I wonder?",
"倉を一棟も濡らさず、あと一年勤め上げること":"To serve one more year without letting a single storehouse get wet",
"倉を十も回った。今日はもう腕が上がらん":"Ten storehouses today. I can't lift my arms anymore.",
"倉守の爺さまが灰汁で洗うて干してくれた。検めの役人も、これなら、と受け取ってくれた":"The old storehouse keeper washed it in lye and dried it. The inspector took it, saying it would do.",
"借りが返せず、田を手放した者がまた一人":"Another one couldn't repay and had to give up his field.",
"借りた賽":"Borrowed dice",
"借りていい？":"Can I borrow it?",
"借りないよりは、ましってこと":"Beats not borrowing at all, I mean.",
"値が先月より上がっとる。市司に言いつけるぞ":"Prices are up from last month. I'll report you to the market office.",
"値と升を見るのが役目":"My job is checking prices and measures.",
"値のことは聞かないどくれ":"Don't ask me about the price.",
"値の上がり方で、誰が買っているかわかる":"From how a price rises, you can tell who's buying.",
"値の札":"A price tag",
"値はどう決まる？":"How are prices set?",
"値は下げないよ。でも一切れおまけ":"I won't lower the price. But here's an extra slice.",
"値は帳面に書いてある":"The prices are in the ledger.",
"値より品よ。安い店には安いわけがある":"Quality over price. A cheap shop is cheap for a reason.",
"偉い人のまねは受ける":"Impressions of important people always go over well.",
"偉い博士が右大臣さまに何か申し上げたらしい":"I hear some great scholar told the Minister of the Right something.",
"側溝の掃除をさぼる家がある":"Some households are skipping their gutter cleaning.",
"側溝は住む者が掃除する決まりだ":"The rule is, residents clean their own gutters.",
"側溝は沿いの家が掃除した（推定）":"Houses along a ditch cleaned it (conjecture)",
"備中":"Bitchu.",
"備中から二十日、歩き通しだ。調の布と鉄を、やっと都に納める。宿はどこも運脚で一杯よ":"Twenty days on foot from Bitchu. At last I deliver the tax cloth and iron to the capital. Every inn's packed with porters.",
"備中から届いた調の布が帳簿と三端合わない":"The tax cloth from Bitchu is three bolts short of the ledger",
"備中から来た男の籍を、去年書き写した":"Last year I copied out the record of a man from Bitchu",
"備中から荷を担いできた、初男だ":"Hatsuo's the name. Hauled this load all the way from Bitchu.",
"備中に妻と子が四人、年寄りの母":"Wife, four children and an aged mother in Bitchu",
"備中の人夫どもの布か。数えたのはわしだ":"The cloth those Bitchu porters brought? I'm the one who counted it.",
"備中の初男がまた泊まっている":"Hatsuo from Bitchu is staying with us again.",
"備中の初男どのと、国の話をした":"Talked about home with Hatsuo from Bitchu.",
"備中の初男どのは、荷を納めたが帰りの糧が三日分しかない。三河の広足どのは、布が黴びて突き返された":"Hatsuo from Bitchu delivered his goods, but has only three days' food for the trip home. Hirotari from Mikawa had his cloth sent back because it had mildewed.",
"備中の初男どのは隣の国じゃ。早う帰れと言うてある":"Hatsuo of Bitchu is from the next province over. I've told him to hurry home.",
"備中の初男どのも、納め待ちで宿代がかさむと言うとった":"Hatsuo from Bitchu says his lodging bill's pilin' up too, waitin' to deliver.",
"備中の初男は、毎年ここで草鞋を買っていく":"Hatsuo from Bitchu buys his sandals here every year.",
"備中の布が三端合わん。どこへ消えた":"Bitchu's cloth is three bolts short. Where did it go?",
"備中の真鳥？ …この五条の坊の者ではない。この坊のことなら、どの家に誰がおるか全部わかる。だが隣の坊のことは知らん":"Matori of Bitchu? …He's not from this ward of Gojo. In this ward I know who lives in every house. But the next ward over, I don't know",
"備中の調の布が三端合わん。どこへ消えたやら":"Bitchu's tax cloth is three bolts short. Where could it have gone?",
"備中の調（布と鉄）を都へ運ぶ運脚。国から二十日ほど歩く":"A tax porter carrying Bitchu's tax goods (cloth and iron) to the capital; about twenty days' walk from home",
"備中の運脚":"The Tax Porter from Bitchu",
"備中の運脚に。帰りの道は長いから":"For the tax porter from Bitchu. It's a long road home.",
"備中国":"Bitchu Province",
"備後から布を担いできた。もう三年前じゃ":"Carried cloth here from Bingo. Three years ago now.",
"備後と備中は隣じゃ。男どのの妻にも、わしが先に知らせてやれる":"Bingo and Bitchu are neighbors. I can get word to his wife before he arrives.",
"備後に妻がいた。三年帰っていない":"Had a wife in Bingo. Hasn't been home in three years",
"備後の言葉が聞こえると眠れる":"When I hear Bingo talk around me, I can sleep.",
"備後国":"Bingo Province",
"僧":"Monk",
"僧坊は冬が寒うて、経を読む声まで震えます":"The monks' quarters are so cold in winter, even our chanting shivers.",
"僧綱所がある寺ゆえ、諸国の僧の出入りが多い":"The office overseeing monks is here, so monks from every province come and go.",
"僧綱所は西寺に置かれた（通説・模型の配置）":"The Sogo-sho (Office of Monastic Affairs) was at Saiji (common view; placement in the model)",
