"元慶の乱（878・通説）":"Gangyo Rebellion (878; commonly accepted)",
"元慶元年（877）菅原道真 文章博士（日本三代実録）":"Gangyo 1 (877), Sugawara no Michizane becomes Professor of Literature (Nihon Sandai Jitsuroku)",
"元日の朝賀に並ぶと、足が冷えて難儀する":"Lining up for the New Year's Day greeting, my feet freeze. It's a trial.",
"元気だったよ":"He's doing well",
"兄ちゃんの炭だ！ 黒麻呂も喜ぶ":"Charcoal from my big brother! Kuromaro will be happy too.",
"兄は怒っとるかのう":"Wonder if my brother's angry.",
"先に来た者の石よ":"The stone belongs to whoever got here first.",
"先に買い占める":"Buy it all first",
"先を急ぐ":"Hurry on",
"先例が見つからぬ日は、帰りの牛車も重い":"On days I find no precedent, even the ox cart home feels heavy.",
