"先例を知りたければ聞け":"If you want to know a precedent, ask me.",
"先月より多いじゃないか":"That's more than last month!",
"先月改めたとき、米六の升は正しかった。…替えたのなら別だがな":"When I checked last month, Komeroku's measure was true. ...Unless he has changed it since.",
"先生、この一節の意味が":"Master, the meaning of this passage...",
