"六角堂の灯が見えた。堂の前で行誉さまが待っておられる。大輔どのは夜通し、姫君のために祈られた":"The lamps of the Rokkaku-do come into view. The monk Gyoyo waits before the hall. Lady Taifu prays all night for the young lady.",
"六角堂の行誉":"Gyoyo of the Rokkaku-do",
