"六角堂の行誉さまに、町の衆の話を伺います":"I go to Master Gyoyo of the Rokkaku-do to hear about the townsfolk.",
"六角堂の行誉さまの堂も、わしが手を入れた":"I worked on Master Gyoyo's hall at the Rokkaku-do too.",
"六角堂の行誉と申す":"I am Gyoyo of the Rokkaku-do.",
