"叔父が受けて、高く蹴り上げた。「おお、続いた！」…叔父はその日いちばん上機嫌だった":"The uncle takes it and kicks it high. \"Oh, it kept going!\" ...He was in the best mood of anyone that day.",
"叔父が落とす前に、こちらで先に蹴り上げる":"Kick it up yourself before he drops it",
