"叔父の庭。四人で輪になる。叔父に鞠が回った。叔父の足もとは、少し危うい":"The uncle's garden. Four of you form a circle. The ball goes to the uncle. His footwork looks a little shaky.",
"叔父の真成が帳簿で夜なべしていた":"Uncle Masanari stayed up all night over his ledgers",
