"叔父は右京の三条に住む。…いや、わしが連れていく。鞠の会では、まず主に挨拶だ。主の前で蹴るときは、主に鞠を回すのを忘れるな":"My uncle lives on Sanjo (Third Avenue) in the western city. ...No, I'll take you. At a kemari gathering, greet the host first. When you play before the host, don't forget to pass him the ball.",
"叔父は民部省の伴真成。帳簿の鬼よ":"My uncle is Tomo no Masanari of the Ministry of Popular Affairs. A demon for ledgers.",
"叔父上の帳簿の数を、ときどき手伝う":"Now and then I help my uncle add up his ledgers.",
"叔父上は帳簿の数が合うまで帰らん。…わしも似たのかもしれん":"My uncle won't go home until the ledger adds up. …Maybe I take after him.",
"取り合いになれば、舟の頭が値を吊り上げるだけなんだがね":"If they fight over it, the boat's boss just jacks up the price, mind.",
"受け取る":"Take it",
