"受領の蓄財（通説）":"Governors amassing wealth (commonly accepted)",
"叡山の円照と申す":"I am Ensho, of Mt. Hiei.",
"叡山の教えを都に広めること":"To spread the teachings of Mt. Hiei in the capital",
"口で言うことより、書いたものを信じる":"I trust what is written over what is said.",
"口は堅いほうでな":"I know how to keep my mouth shut.",
"口添えを探す":"Find someone to vouch",
"口減らしで幼い頃に中納言家へ。牛の扱いが上手く、そのまま牛飼に。口が軽い。主人の悪口は言わないが、主人の周りの噂はよく喋る":"Sent young to the Middle Counselor's house, one less mouth for his family to feed. Good with oxen, he stayed on as an ox-boy. Loose-lipped: never speaks ill of his master, but gossips freely about those around him",
"古い市人と、昔の賑わいを語る夜もある":"Some nights I talk of the old bustle with veteran merchants.",
"古い書き付けから、長雨の歌が三首出てきた":"Three poems on the long rains turned up among the old notes.",
"古い柱を支え木で浮かせて、抜く。新しい柱を、綱で起こす。…鉄の童、綱の端を持て。せえの":"Prop up the old pillar, lift it, pull it out. Raise the new one with ropes. ...Iron Child, grab the end of the rope. Ready... heave!",
"古い歌の書き付けが、また一山届いた":"Another pile of old poem notes has arrived.",
"古い歌の書き付けを、ひまを見ては写しておる。従兄の友則どの、躬恒・忠岑とも、いつか一つの集にしたいと話しておるのだ":"When I have time, I copy out old poems from scraps. With my cousin Tomonori, and Mitsune and Tadamine, I talk of someday making them one collection.",
