"史記天官書「昴為髦頭、胡星也」。「すばる」は古くからの和語で、「昴」の字を当てたのは後世（要確認）":"Shiji, Treatise on Astronomy: \"Subaru is the Hair Head, the Barbarian star.\" The word Subaru is old Japanese; the character was applied later (to be confirmed).",
