"史記天官書（太微）。天文密奏は職員令（天文博士）。客星・彗星を不吉とする読みは漢籍":"Shiji, Treatise on Astronomy (Taibi). Secret astronomical reports come from the Statutes on Offices (master of astronomy). Reading guest stars and comets as bad omens is from Chinese books.",
