"小式部さんの話を聞く":"Hear Koshikibu's own story",
"小式部どのとは？":"Who is Lady Koshikibu?",
"小式部どのに。物語の合間に読んでくれと":"For Koshikibu. Ask her to read it between her tales.",
"小式部どのは、どんな顔をなさるだろう":"I wonder what face Lady Koshikibu will make.",
"小菊":"Kogiku",
"小菊、その字は「山」だ。よう書けた":"Kogiku, that character means 'mountain.' Nicely written.",
