"山城国愛宕郡":"Otagi District, Yamashiro Province",
"山城国愛宕郡、小野の里の炭焼きの家の三男":"Third son of a charcoal-burner's family in Ono village, Otagi District, Yamashiro Province",
"山城国愛宕郡小野の里":"Ono village, Otagi District, Yamashiro Province",
"山城国葛野郡":"Kadono District, Yamashiro Province",
