"日本三代実録 仁和3年（887）8月条":"Nihon Sandai Jitsuroku (True History of Three Reigns), Ninna 3 (887), 8th month entry",
"日本三代実録 貞観5年5月20日条。六柱の最後の一人は諸説":"Nihon Sandai Jitsuroku, Jogan 5, 5th month, 20th day. Views vary on the last of the six",
