"盗人の詮議より、孫の夜更かしが問題よ":"Never mind the thief. The real trouble is the boy staying up late.",
"盗人の話なら検非違使へ。ここは籍と土地の役所だ":"Thieves go to the kebiishi. This is the office for records and land",
"盗人の話を聞く":"Ask about the thief",
"盗人の通る道？ 元は盗人の俺に聞くか。…いいだろう":"The routes thieves take? You're asking me, an ex-thief? ...All right.",
