"盗賊が出て、荷を半分取られた":"Bandits came and took half our load.",
"監察の弾正台が、今は見張る相手もおらぬとは":"The Board of Censors, with no one left to watch over.",
"盥での洗濯（推定）":"Washing in a tub (estimate)",
