"餅は、その時分のがうまいのさ。どの時分の話がいい？":"Rice cakes taste best in their own season. Which season shall I tell you about?",
"餅はいかが、温かいよ":"Rice cakes? Nice and warm.",
"餅を搗く音が聞こえたら確かだ":"If you hear rice cakes being pounded, it's certain.",
"餅女":"Mochime",
"餅女さんに。餅を焼くには小野の炭が一番":"For Mochime. Nothing beats Ono charcoal for toasting rice cakes.",
"餅女の餅は、待つ間の楽しみさ":"Mochime's rice cakes are something to look forward to while I wait.",
"養子の基経（関白・891没）がその後を継ぎ、基経の子がいまの左大臣 時平。藤原北家の栄えは、ここから始まる。":"His adopted son Mototsune (chancellor; d. 891) followed him, and Mototsune's son is the current Minister of the Left, Tokihira. The glory of the Northern Fujiwara starts here.",
"香りを確かめただけで":"I only checked the smell, sir...",
"馬が一頭、道で足を痛めた":"One of the horses hurt its leg on the road.",
"馬が驚く！ 鉄の童、厩へは寄るな":"You'll spook the horses! Iron Child, keep away from the stables.",
"馬と弓と衛府":"Horses, Bows and the Palace Guards",
