"馬の目を見ればわかる":"Look a horse in the eye and you'll know.",
"馬の腹具合で、その日の忙しさが決まる":"How the horses' bellies are doing decides how busy my day is.",
"馬は臆病でな。急に後ろへ回ると蹴られるぞ":"Horses are skittish. Step behind one suddenly and you'll get kicked.",
"馬より速く歩けるのか。一度競べてみたい":"Can it go faster than a horse? I'd like to race it once.",
"馬を一頭、自分のものにしたい":"To own a horse of his own",
"馬を無事に納めて帰ること":"To deliver the horses safely and go home",
