"馬栓棒は二段。上だけ外すと、馬は下をくぐる":"The stall bars come in two. Take off just the top one, and the horse ducks under.",
"馬栓棒を外すときは、必ず声をかけろ":"Always call out before you take down the stall bar.",
"駒牽きの日は、ここがいちばん賑わう":"On horse presentation day, this place is busiest of all.",
"駒牽きの稽古、今日は何頭だ":"How many horses in today's drill for the horse presentation?",
"騎射の手結が近い。馬寮から馬を借りねば":"The mounted archery trials are near. I must borrow a horse from the Horse Bureau.",
"騎射の的が新しくなった":"The mounted archery targets were replaced",
