"高いか。なら座って待て。急ぐ用など、無いじゃろう":"Still high? Then sit and wait. You have nowhere to hurry to.",
"高い所で一日。夜は足が震える":"A whole day up high. At night my legs shake.",
"高い所は好きだ":"I like high places.",
"高い！ 隣は四升だったぞ":"Too much! Next door it was four measures!",
"高く上げて、百の技を見せる":"Kick it high, show a hundred tricks",
