"高野の山で、今も祈っておられると申します":"They say he is still praying on Mt. Koya, even now.",
"高野の山で修行を始め、東寺に移った。塔の心柱を百人で立てた話を老僧から聞くのが好き。西寺の賢心とは、東寺と西寺の張り合いを冗談にする仲":"He began his training on Mt. Koya and moved to Toji temple. He loves hearing old monks tell how a hundred men raised the pagoda's central pillar. He and Kenshin of Saiji temple joke about the rivalry between their temples",
